//! Hashing that mirrors `std::hash` as libstdc++ implements it.
//!
//! `tsl::hopscotch_map` defaults to `std::hash<Key>`, and the observable state
//! of the map (which bucket an entry lands in, and therefore
//! `overflow_size()`) depends on the exact hash values. libstdc++ hashes every
//! primitive integer to its own bit pattern widened to `size_t`, so the port
//! has to do the same instead of reaching for Rust's `SipHash`.

/// Equivalent of `std::hash<T>`: maps a key to the value libstdc++ would.
pub trait CxxHash {
    fn hash_value(&self) -> u64;
}

/// libstdc++ hashes the narrow integer types by widening them to `size_t`,
/// sign-extending the signed ones. `as u64` reproduces both conversions.
macro_rules! identity_hash {
    ($($t:ty),*) => {
        $(
            impl CxxHash for $t {
                #[inline]
                fn hash_value(&self) -> u64 {
                    *self as u64
                }
            }
        )*
    };
}

identity_hash!(i8, i16, i32, i64, isize, u8, u16, u32, u64, usize, char, bool);

/// `MurmurHash64A` with libstdc++'s seed, used by `std::hash` for every type
/// that hashes a byte range (`std::string`, `std::string_view`, ...).
pub fn murmur_hash64a(bytes: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;

    let mut h = seed ^ (bytes.len() as u64).wrapping_mul(M);

    let mut chunks = bytes.chunks_exact(8);
    for chunk in &mut chunks {
        let mut k = u64::from_le_bytes(chunk.try_into().unwrap());
        k = k.wrapping_mul(M);
        k ^= k >> R;
        k = k.wrapping_mul(M);

        h ^= k;
        h = h.wrapping_mul(M);
    }

    let tail = chunks.remainder();
    if !tail.is_empty() {
        let mut k: u64 = 0;
        for (i, &b) in tail.iter().enumerate() {
            k |= (b as u64) << (8 * i);
        }
        h ^= k;
        h = h.wrapping_mul(M);
    }

    h ^= h >> R;
    h = h.wrapping_mul(M);
    h ^= h >> R;
    h
}

/// The seed libstdc++ passes to `_Hash_impl::hash` for `std::string` & friends.
pub const STRING_HASH_SEED: u64 = 0xc70f_6907;

impl CxxHash for str {
    #[inline]
    fn hash_value(&self) -> u64 {
        murmur_hash64a(self.as_bytes(), STRING_HASH_SEED)
    }
}

impl CxxHash for String {
    #[inline]
    fn hash_value(&self) -> u64 {
        self.as_str().hash_value()
    }
}

impl CxxHash for [u8] {
    #[inline]
    fn hash_value(&self) -> u64 {
        murmur_hash64a(self, STRING_HASH_SEED)
    }
}

impl<T: CxxHash + ?Sized> CxxHash for &T {
    #[inline]
    fn hash_value(&self) -> u64 {
        (**self).hash_value()
    }
}

