//! `tsl::hh::power_of_two_growth_policy`, the default growth policy of
//! `tsl::hopscotch_map`.
//!
//! The bucket count is always a power of two so that mapping a hash to a
//! bucket is a mask instead of a modulo. A bucket count of zero is legal and
//! means "no buckets allocated yet".

/// The map refuses to grow past this many buckets, mirroring the
/// `std::length_error` thrown by the C++ policy.
pub const MAX_BUCKET_COUNT: usize = (usize::MAX / 2) + 1;

#[derive(Clone, Copy, Debug)]
pub struct PowerOfTwoGrowthPolicy {
    /// `bucket_count - 1`, or 0 when there are no buckets.
    mask: usize,
}

impl PowerOfTwoGrowthPolicy {
    /// Rounds `min_bucket_count` up to a power of two and returns the policy
    /// together with the bucket count it settled on.
    pub fn new(min_bucket_count: usize) -> (Self, usize) {
        if min_bucket_count == 0 {
            return (Self { mask: 0 }, 0);
        }

        let bucket_count = round_up_to_power_of_two(min_bucket_count);
        (
            Self {
                mask: bucket_count - 1,
            },
            bucket_count,
        )
    }

    /// Index of the bucket a hash belongs to.
    #[inline]
    pub fn bucket_for_hash(&self, hash: u64) -> usize {
        (hash as usize) & self.mask
    }

    /// Bucket count to grow to when the load factor is reached. Doubling from
    /// an empty map yields two buckets.
    pub fn next_bucket_count(&self) -> usize {
        if self.mask == MAX_BUCKET_COUNT - 1 {
            length_error();
        }

        (self.mask + 1) * 2
    }

    pub fn max_bucket_count(&self) -> usize {
        MAX_BUCKET_COUNT
    }
}

/// Smallest power of two `>= value`. Panics like the C++ policy's
/// `std::length_error` if the value cannot be represented.
pub fn round_up_to_power_of_two(value: usize) -> usize {
    if value > MAX_BUCKET_COUNT {
        length_error();
    }
    if value <= 1 {
        return value;
    }

    // `value - 1` keeps exact powers of two unchanged.
    1usize << (usize::BITS - (value - 1).leading_zeros())
}

fn length_error() -> ! {
    panic!("The map exceeds its maxmimum size.");
}

/// `size_type(std::ceil(float(count) / max_load_factor))`, the expression
/// `reserve()` and `rehash()` use to size the bucket array.
///
/// The division and the `ceil` happen in `float`, not `double`, and the
/// narrowing back to `size_t` has to reproduce what x86-64 actually does for
/// out-of-range values -- see [`f32_to_usize`].
pub fn buckets_for_size(count: usize, max_load_factor: f32) -> usize {
    f32_to_usize((count as f32 / max_load_factor).ceil())
}

/// `static_cast<std::size_t>(f)` as compiled for x86-64.
///
/// C++ leaves the conversion undefined when `f` is outside the range of
/// `size_t`, and Rust's `as` saturates instead, so the two disagree exactly
/// where a caller passes a negative `int` that wrapped into a huge `size_t`
/// (`map.reserve(-5)`). GCC emits a compare against 2^63 followed by
/// `cvttss2si`, whose out-of-range result is the "integer indefinite" value
/// `i64::MIN`; for `reserve(-5)` that path wraps around to 0 buckets, which is
/// what the C++ binary prints.
pub fn f32_to_usize(f: f32) -> usize {
    const TWO_POW_63: f32 = 9_223_372_036_854_775_808.0;

    // `cvttss2si` on a value it cannot represent (or on a NaN) yields i64::MIN.
    fn cvttss2si(f: f32) -> i64 {
        if f.is_nan() || f < -TWO_POW_63 || f >= TWO_POW_63 {
            i64::MIN
        } else {
            f as i64
        }
    }

    let bits = if f < TWO_POW_63 {
        cvttss2si(f) as u64
    } else {
        // Signed conversion of `f - 2^63`, then flip the sign bit back on.
        (cvttss2si(f - TWO_POW_63) as u64) ^ (1u64 << 63)
    };

    bits as usize
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rounds_up_to_powers_of_two() {
        assert_eq!(round_up_to_power_of_two(0), 0);
        assert_eq!(round_up_to_power_of_two(1), 1);
        assert_eq!(round_up_to_power_of_two(2), 2);
        assert_eq!(round_up_to_power_of_two(3), 4);
        assert_eq!(round_up_to_power_of_two(17), 32);
        assert_eq!(round_up_to_power_of_two(32), 32);
    }

    #[test]
    fn sizes_bucket_array_like_the_cxx_reserve() {
        // Values cross-checked against the compiled C++ binary.
        for &(count, buckets) in &[
            (0usize, 0usize),
            (1, 2),
            (2, 3),
            (3, 4),
            (14, 16),
            (15, 17),
            (28, 32),
            (29, 33),
            (115, 128),
            (116, 129),
        ] {
            assert_eq!(buckets_for_size(count, 0.9), buckets, "count {count}");
        }
    }

    #[test]
    fn wraps_out_of_range_floats_like_x86() {
        // `reserve(static_cast<size_t>(-5))` on x86-64 asks for 0 buckets.
        let wrapped = (-5i32) as usize;
        assert_eq!(buckets_for_size(wrapped, 0.9), 0);
    }
}

