//! One slot of the bucket array.
//!
//! A bucket carries two things: the entry stored *in* the slot (which may
//! belong to an earlier bucket), and the neighborhood info of the bucket
//! itself -- a bitmap saying which of the `NEIGHBORHOOD_SIZE` slots starting
//! here hold entries whose home bucket is this one, plus a flag saying whether
//! some entry that hashes here had to go to the overflow list.

/// Number of consecutive slots an entry may be stored in, counted from its home
/// bucket. This is `tsl::hopscotch_map`'s default `NeighborhoodSize`; 62 bits of
/// bitmap plus the overflow flag fit in one `u64`.
pub const NEIGHBORHOOD_SIZE: usize = 62;

const NEIGHBORHOOD_MASK: u64 = (1u64 << NEIGHBORHOOD_SIZE) - 1;
const OVERFLOW_FLAG: u64 = 1u64 << NEIGHBORHOOD_SIZE;

#[derive(Clone, Debug)]
pub struct Bucket<K, V> {
    infos: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Default for Bucket<K, V> {
    fn default() -> Self {
        Self {
            infos: 0,
            entry: None,
        }
    }
}

impl<K, V> Bucket<K, V> {
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entry.is_none()
    }

    #[inline]
    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    #[inline]
    pub fn entry_mut(&mut self) -> Option<&mut (K, V)> {
        self.entry.as_mut()
    }

    /// Stores an entry in this slot. The caller is responsible for recording it
    /// in the home bucket's neighborhood.
    #[inline]
    pub fn set_entry(&mut self, key: K, value: V) {
        debug_assert!(self.is_empty());
        self.entry = Some((key, value));
    }

    #[inline]
    pub fn take_entry(&mut self) -> Option<(K, V)> {
        self.entry.take()
    }

    /// Bitmap of the offsets, relative to this bucket, that hold entries
    /// belonging to it.
    #[inline]
    pub fn neighborhood(&self) -> u64 {
        self.infos & NEIGHBORHOOD_MASK
    }

    #[inline]
    pub fn has_neighbor(&self, offset: usize) -> bool {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.infos & (1u64 << offset) != 0
    }

    #[inline]
    pub fn set_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(!self.has_neighbor(offset));
        self.infos |= 1u64 << offset;
    }

    #[inline]
    pub fn clear_neighbor(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(self.has_neighbor(offset));
        self.infos &= !(1u64 << offset);
    }

    /// Whether an entry hashing to this bucket lives in the overflow list.
    #[inline]
    pub fn has_overflow(&self) -> bool {
        self.infos & OVERFLOW_FLAG != 0
    }

    #[inline]
    pub fn set_overflow(&mut self) {
        self.infos |= OVERFLOW_FLAG;
    }
}

