//! The hopscotch hash table that backs [`HopscotchMap`](map::HopscotchMap).
//!
//! Layout, in the shape of `tsl::hopscotch_map`:
//!
//! * The bucket array holds `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, so
//!   the neighborhood of the last real bucket never runs off the end.
//! * An entry always lives within `NEIGHBORHOOD_SIZE` slots of its home
//!   bucket, and the home bucket records the offset in its bitmap. Lookup
//!   therefore touches one cache line's worth of contiguous slots.
//! * When a free slot can be neither found nor "hopped" close enough, the entry
//!   goes to an overflow list and the home bucket's overflow flag is set.

pub mod bucket;
pub mod map;

use std::collections::VecDeque;

use crate::growth::{buckets_for_size, PowerOfTwoGrowthPolicy};
use crate::hash::CxxHash;

use bucket::{Bucket, NEIGHBORHOOD_SIZE};

/// `tsl::hopscotch_map`'s default maximum load factor.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.9;

/// Where a key was found.
enum Slot {
    /// Index into the bucket array.
    Bucket(usize),
    /// Index into the overflow list.
    Overflow(usize),
}

pub struct HopscotchHash<K, V> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, or empty when there are no
    /// buckets at all.
    buckets: Vec<Bucket<K, V>>,
    /// Entries whose neighborhood was full. `std::list` in C++; the map only
    /// ever appends and scans, so a deque behaves the same.
    overflow: VecDeque<(K, V)>,
    growth: PowerOfTwoGrowthPolicy,
    bucket_count: usize,
    nb_elements: usize,
    max_load_factor: f32,
    /// `bucket_count * max_load_factor`, truncated; growth happens once the
    /// element count reaches it.
    load_threshold: usize,
}

impl<K, V> HopscotchHash<K, V> {
    pub fn with_bucket_count(min_bucket_count: usize, max_load_factor: f32) -> Self {
        let (growth, bucket_count) = PowerOfTwoGrowthPolicy::new(min_bucket_count);

        let mut table = Self {
            buckets: Vec::new(),
            overflow: VecDeque::new(),
            growth,
            bucket_count,
            nb_elements: 0,
            max_load_factor,
            load_threshold: 0,
        };
        table.allocate_buckets();
        table.update_load_threshold();
        table
    }

    fn allocate_buckets(&mut self) {
        self.buckets = if self.bucket_count == 0 {
            Vec::new()
        } else {
            let mut buckets = Vec::new();
            buckets.resize_with(self.bucket_count + NEIGHBORHOOD_SIZE - 1, Bucket::default);
            buckets
        };
    }

    fn update_load_threshold(&mut self) {
        self.load_threshold =
            crate::growth::f32_to_usize(self.bucket_count as f32 * self.max_load_factor);
    }

    #[inline]
    pub fn len(&self) -> usize {
        self.nb_elements
    }

    #[inline]
    pub fn is_empty(&self) -> bool {
        self.nb_elements == 0
    }

    #[inline]
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    #[inline]
    pub fn max_bucket_count(&self) -> usize {
        self.growth.max_bucket_count()
    }

    #[inline]
    pub fn overflow_size(&self) -> usize {
        self.overflow.len()
    }

    #[inline]
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            return 0.0;
        }
        self.nb_elements as f32 / self.bucket_count as f32
    }

    pub fn clear(&mut self) {
        for slot in &mut self.buckets {
            *slot = Bucket::default();
        }
        self.overflow.clear();
        self.nb_elements = 0;
    }

    /// Entries in bucket order, then the overflow list -- the order
    /// `tsl::hopscotch_map`'s iterators produce.
    pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
        self.buckets
            .iter()
            .filter_map(Bucket::entry)
            .chain(self.overflow.iter())
            .map(|(key, value)| (key, value))
    }
}

impl<K: CxxHash + Eq, V> HopscotchHash<K, V> {
    /// `max_load_factor` is clamped the way the C++ setter clamps it.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        self.max_load_factor = max_load_factor.clamp(0.1, 0.95);
        self.update_load_threshold();
    }

    /// Sizes the table so `count` elements fit without a rehash.
    pub fn reserve(&mut self, count: usize) {
        self.rehash(buckets_for_size(count, self.max_load_factor));
    }

    /// Rebuilds the table with at least `count` buckets, never dropping below
    /// what the current element count needs.
    pub fn rehash(&mut self, count: usize) {
        let needed = buckets_for_size(self.nb_elements, self.max_load_factor);
        self.rehash_impl(count.max(needed));
    }

    fn rehash_impl(&mut self, count: usize) {
        let mut rehashed = Self::with_bucket_count(count, self.max_load_factor);

        let old_buckets = std::mem::take(&mut self.buckets);
        let old_overflow = std::mem::take(&mut self.overflow);
        let entries = old_buckets
            .into_iter()
            .filter_map(|mut slot| slot.take_entry())
            .chain(old_overflow);

        for (key, value) in entries {
            rehashed.insert_unique(key, value);
        }

        *self = rehashed;
    }

    fn grow(&mut self) {
        self.rehash_impl(self.growth.next_bucket_count());
    }

    /// Inserts `key`/`value` unless `key` is already present. Returns whether
    /// an entry was added.
    pub fn insert(&mut self, key: K, value: V) -> bool {
        if self.locate(&key).is_some() {
            return false;
        }

        if self.nb_elements >= self.load_threshold {
            self.grow();
        }

        self.insert_unique(key, value);
        true
    }

    /// Inserts an entry known not to be in the table yet.
    fn insert_unique(&mut self, key: K, value: V) {
        let hash = key.hash_value();

        loop {
            let ibucket = self.growth.bucket_for_hash(hash);

            let Some(iempty) = self.find_empty_slot(ibucket) else {
                // Not a single free slot from the home bucket onwards.
                self.grow();
                continue;
            };

            let iempty = self.hop_empty_slot_closer(ibucket, iempty);
            let offset = iempty - ibucket;

            if offset < NEIGHBORHOOD_SIZE {
                self.buckets[iempty].set_entry(key, value);
                self.buckets[ibucket].set_neighbor(offset);
            } else {
                self.overflow.push_back((key, value));
                self.buckets[ibucket].set_overflow();
            }

            self.nb_elements += 1;
            return;
        }
    }

    /// First free slot at or after `ibucket`.
    fn find_empty_slot(&self, ibucket: usize) -> Option<usize> {
        self.buckets
            .iter()
            .enumerate()
            .skip(ibucket)
            .find(|(_, slot)| slot.is_empty())
            .map(|(index, _)| index)
    }

    /// Walks the free slot at `iempty` back towards `ibucket` by moving entries
    /// forward into it -- the "hop" of hopscotch hashing. Returns the index of
    /// the free slot it ended up at, which is still out of reach if no entry
    /// could be moved.
    fn hop_empty_slot_closer(&mut self, ibucket: usize, mut iempty: usize) -> usize {
        while iempty - ibucket >= NEIGHBORHOOD_SIZE {
            // Only buckets this close to `iempty` can reach it at all.
            let first_candidate = iempty + 1 - NEIGHBORHOOD_SIZE;

            let mut hopped = false;
            for candidate in first_candidate..iempty {
                // Its closest entry is the one that frees up the lowest slot.
                let neighborhood = self.buckets[candidate].neighborhood();
                if neighborhood == 0 {
                    continue;
                }

                let offset = neighborhood.trailing_zeros() as usize;
                let isource = candidate + offset;
                if isource >= iempty {
                    continue;
                }

                let (key, value) = self.buckets[isource].take_entry().expect("bitmap desync");
                self.buckets[iempty].set_entry(key, value);
                self.buckets[candidate].clear_neighbor(offset);
                self.buckets[candidate].set_neighbor(iempty - candidate);

                iempty = isource;
                hopped = true;
                break;
            }

            if !hopped {
                break;
            }
        }

        iempty
    }

    fn locate(&self, key: &K) -> Option<Slot> {
        if self.bucket_count == 0 {
            return None;
        }

        let ibucket = self.growth.bucket_for_hash(key.hash_value());
        let home = &self.buckets[ibucket];

        let mut neighborhood = home.neighborhood();
        while neighborhood != 0 {
            let offset = neighborhood.trailing_zeros() as usize;
            neighborhood &= neighborhood - 1;

            let index = ibucket + offset;
            if self.buckets[index].entry().is_some_and(|(k, _)| k == key) {
                return Some(Slot::Bucket(index));
            }
        }

        if home.has_overflow() {
            if let Some(index) = self.overflow.iter().position(|(k, _)| k == key) {
                return Some(Slot::Overflow(index));
            }
        }

        None
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        match self.locate(key)? {
            Slot::Bucket(index) => self.buckets[index].entry().map(|(_, v)| v),
            Slot::Overflow(index) => self.overflow.get(index).map(|(_, v)| v),
        }
    }

    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        match self.locate(key)? {
            Slot::Bucket(index) => self.buckets[index].entry_mut().map(|(_, v)| v),
            Slot::Overflow(index) => self.overflow.get_mut(index).map(|(_, v)| v),
        }
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.locate(key).is_some()
    }
}

