//! `tsl::hopscotch_map`: the public map API over [`HopscotchHash`].

use crate::hash::CxxHash;

use super::{HopscotchHash, DEFAULT_MAX_LOAD_FACTOR};

pub struct HopscotchMap<K, V> {
    table: HopscotchHash<K, V>,
}

impl<K, V> Default for HopscotchMap<K, V> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K, V> HopscotchMap<K, V> {
    /// An empty map with no buckets allocated, like the default-constructed
    /// C++ map.
    pub fn new() -> Self {
        Self {
            table: HopscotchHash::with_bucket_count(0, DEFAULT_MAX_LOAD_FACTOR),
        }
    }

    /// `hopscotch_map(bucket_count)`: allocates at least `bucket_count`
    /// buckets, rounded up to a power of two.
    pub fn with_bucket_count(bucket_count: usize) -> Self {
        Self {
            table: HopscotchHash::with_bucket_count(bucket_count, DEFAULT_MAX_LOAD_FACTOR),
        }
