#[test]
fn overflows_when_a_whole_neighborhood_collides() {
    // Identity hashing means every one of these keys has bucket 0 as its
    // home for any bucket count up to 2^20, so only NEIGHBORHOOD_SIZE of
    // them can be stored in the bucket array.
    let entries: Vec<u64> = (1..=100).map(|i: u64| i << 20).collect();

    let mut map: HopscotchMap<u64, u64> = HopscotchMap::new();
    for &key in &entries {
        assert!(map.insert(key, key));
    }

    assert_eq!(map.len(), entries.len());
    assert_eq!(map.overflow_size(), entries.len() - NEIGHBORHOOD_SIZE);
    for &key in &entries {
        assert_eq!(map.get(&key), Some(&key));
    }
}

