    fn string_keys_hash_and_round_trip() {
        let mut map: HopscotchMap<String, usize> = HopscotchMap::with_capacity(64);
        for i in 0..200 {
            map.insert(format!("key-{i}"), i);
        }

        assert_eq!(map.len(), 200);
        assert_eq!(map.get(&"key-137".to_string()), Some(&137));
        assert!(!map.contains_key(&"missing".to_string()));
    }
