//! The slivers of the C++ runtime the test programs lean on.
//!
//! `test18.cpp` reaches its argument through `std::stoi`, whose quirks are
//! observable: it skips leading whitespace, accepts a sign, stops at the first
//! non-digit instead of rejecting the string, and throws on a missing or
//! out-of-range number. An uncaught throw takes the process down through
//! `std::terminate`, which prints a fixed message and raises `SIGABRT` -- so a
//! faithful port has to abort too, not exit cleanly.

use std::io::Write;

/// `std::stoi(str)` with the default base of 10.
///
/// Aborts the way an uncaught `std::invalid_argument` / `std::out_of_range`
/// would when the string holds no number or a number outside `int`.
pub fn stoi(str: &str) -> i32 {
    let bytes = str.as_bytes();
    let mut index = 0;

    // `strtol` skips leading whitespace, as classified by the "C" locale.
    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'-') => {
            index += 1;
            true
        }
        Some(b'+') => {
            index += 1;
            false
        }
        _ => false,
    };

    let digits_start = index;
    // Accumulate in i64: `strtol` works in `long`, and `stoi` range-checks the
    // result against `int` afterwards.
    let mut magnitude: i64 = 0;
    let mut overflowed = false;

    while let Some(digit) = bytes.get(index).and_then(|b| (*b as char).to_digit(10)) {
        magnitude = magnitude * 10 + digit as i64;
        if magnitude > i32::MAX as i64 + 1 {
            overflowed = true;
            break;
        }
        index += 1;
    }

    if index == digits_start {
        terminate("std::invalid_argument", "stoi");
    }

    let value = if negative { -magnitude } else { magnitude };
    if overflowed || value < i32::MIN as i64 || value > i32::MAX as i64 {
        terminate("std::out_of_range", "stoi");
    }

    value as i32
}

/// What `std::string(argv[n])` does when `argv[n]` is the null terminator of the
/// argument vector: constructing a `std::string` from `nullptr` throws
/// `std::logic_error`.
pub fn string_from_null() -> ! {
    terminate("std::logic_error", "basic_string::_S_construct null not valid");
}

/// `std::terminate` on an uncaught exception: the verbose handler prints the
/// exception's type and `what()`, then `abort()` raises `SIGABRT`.
pub fn terminate(exception_type: &str, what: &str) -> ! {
    let mut stderr = std::io::stderr().lock();
    let _ = writeln!(
        stderr,
        "terminate called after throwing an instance of '{exception_type}'\n  what():  {what}"
    );
    let _ = stderr.flush();

    std::process::abort();
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_like_stoi() {
        // Cross-checked against the compiled C++ binary.
        assert_eq!(stoi("18"), 18);
        assert_eq!(stoi("+7"), 7);
        assert_eq!(stoi("007"), 7);
        assert_eq!(stoi("  -3"), -3);
        assert_eq!(stoi("\t9"), 9);
        assert_eq!(stoi("-0"), 0);
        // Trailing garbage is ignored rather than rejected.
        assert_eq!(stoi("12xyz"), 12);
        assert_eq!(stoi("0x10"), 0);
        assert_eq!(stoi("3.9"), 3);
        assert_eq!(stoi("2147483647"), i32::MAX);
        assert_eq!(stoi("-2147483648"), i32::MIN);
    }
}

