//! A pure-`std` Rust port of `tsl::hopscotch_map`.
//!
//! Hopscotch hashing is open addressing with a bounded probe: every entry is
//! stored within a fixed-size *neighborhood* of its home bucket, and the home
//! bucket keeps a bitmap of the offsets it owns. Lookups therefore scan a short
//! contiguous run of slots, and inserts that find no room nearby "hop" existing
//! entries forward to open one up.
//!
//! The port keeps the observable behaviour of the C++ original -- bucket
//! counts, load-factor growth points, and `overflow_size()` -- so programs
//! written against `tsl::hopscotch_map` produce identical output.

pub mod cxx;
pub mod growth;
pub mod hash;
pub mod hopscotch;

pub use hash::CxxHash;
pub use hopscotch::map::HopscotchMap;
pub use hopscotch::{HopscotchHash, DEFAULT_MAX_LOAD_FACTOR};

