//! Port of `tests/test18.cpp`: reserve a `hopscotch_map` for `count` entries,
//! fill it, and report `size() / bucket_count() / overflow_size()`.
//!
//! The library modules are declared here with explicit paths so this file
//! builds both as the `test18` Cargo target and on its own via
//! `rustc test18.rs`.

#[path = "src/cxx.rs"]
mod cxx;
#[path = "src/growth.rs"]
mod growth;
#[path = "src/hash.rs"]
mod hash;
#[path = "src/hopscotch/mod.rs"]
mod hopscotch;

use hopscotch::map::HopscotchMap;

fn main() {
    let argv: Vec<String> = std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect();

    let mut count: i32 = 18;
    if argv.len() > 1 && argv[1] == "--a" {
        // `argv[2]` is the null terminator of the argument vector when the flag
        // came without a value, and `std::string(nullptr)` throws.
        let arg = argv.get(2).map_or_else(|| cxx::string_from_null(), String::as_str);
        count = cxx::stoi(arg);
    }

    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    // A negative count sign-extends into a huge `size_t` here, exactly as it
    // does in C++.
    map.reserve(count as usize);

    let mut i: i32 = 0;
    while i < count {
        map.insert(i, i.wrapping_mul(14));
        i += 1;
    }

    println!(
        "{} {} {}",
        map.len(),
        map.bucket_count(),
        map.overflow_size()
    );
}

